+/// Finished `return_top_k_logprobs` output for one choice.
+pub(super) struct TopKLogprobs {
+    /// Present with `return_token_logprobs`.
+    pub sampled: Option<Vec<f64>>,
+    pub top_k: TopKBlock,
+}
