+/// Top-k candidates (arrays as base64 segments).
+pub(super) struct TopKBlock {
+    pub num_positions: usize,
+    pub k: usize,
+    pub token_ids: Vec<Bytes>,
+    pub logprobs: Vec<Bytes>,
+}
